import os
import json
#
from mlx_vlm import generate
#
from prompt import NID_JSON, build_chat_prompt
#

# Code generated by Claude; manually verified to make sure it is correct
# Reason: simple extraction and mapping to JSON Schema

MAX_GEN_TOKENS = 2048

with open(NID_JSON, encoding = "utf-8") as f:
    NID_SCHEMA = json.load(f)

#

def generate_json(model, processor, img_path : str, max_tokens : int = MAX_GEN_TOKENS) -> str:
    # Free generation (not teacher-forced) with the same prompt as
    # training, greedy so the output is reproducible.
    prompt = build_chat_prompt(processor, img_path)
    res = generate(model.model, processor, prompt, image = [img_path], max_tokens = max_tokens, temperature = 0.0)
    return res.text

def extract_json(text : str):
    # Drops any thinking the model still did, then takes the outermost
    # {...} so code fences or text around the JSON are ignored.
    text = text.split("</think>")[-1]
    start, end = text.find("{"), text.rfind("}")
    if start == -1 or end < start:
        return None
    try:
        out = json.loads(text[start:end + 1])
    except json.JSONDecodeError:
        return None
    return out if isinstance(out, dict) else None

def to_schema(pred : dict, schema : dict = NID_SCHEMA) -> dict:
    # Same keys and order as the NID schema: missing keys get the
    # schema's empty value, keys outside the schema are dropped.
    return {key: pred.get(key, default) for key, default in schema.items()}

def save_json(name : str, text : str, json_dir : str):
    # Only the JSON is saved, never the thinking. If no valid JSON
    # object can be found, an empty schema is saved instead, so
    # eval.py scores it as all fields missed.
    os.makedirs(json_dir, exist_ok = True)
    pred = extract_json(text)
    if pred is None:
        print(f"No valid JSON in the output for {name}, saving an empty schema")
        pred = {}
    with open(os.path.join(json_dir, f"{name}.json"), "w", encoding = "utf-8") as f:
        json.dump(to_schema(pred), f, ensure_ascii = False, indent = 4)
